#!/usr/bin/env python3
"""Phase 0 hotspot scan: read-only, no model. Usage: phase0.py <repo-root> <out-json>."""
import json, os, re, subprocess, sys, collections

root, out = sys.argv[1], sys.argv[2]
files = subprocess.run(['git', '-C', root, 'ls-files'], capture_output=True, text=True).stdout.split('\n')
SKIP = re.compile(r'(^|/)(node_modules|target)/|\.snap$|pnpm-lock|Cargo\.lock|^\.entire/|^mutants\.out|CHANGELOG\.md$|^\.changeset/|\.(png|svg|woff2?|json|md|toml|trycmd)$')
CODE_EXT = {'rs': 'rust', 'ts': 'ts', 'tsx': 'ts', 'mjs': 'ts', 'js': 'ts', 'py': 'py', 'yml': 'yaml', 'sh': 'sh'}
HIST = re.compile(r'\b(previously|used to|no longer|now delegates|formerly|legacy|as of|for now|workaround|kept for compat\w*|reserved|'
                  r'review finding|audit|earlier version|was (?:changed|removed|added|renamed)|now (?:uses|reads|returns|calls|takes)|'
                  r'since #?\d|PR #\d+|#\d{2,4}\b|trail \d+)', re.I)

def is_fixture(p):
    return p.startswith('fixtures/') or '/fixtures/' in p or p.startswith('apps/oracle/node_modules')

def comment_style(lang):
    return '#' if lang in ('py', 'yaml', 'sh') else '//'

SOFT = {
    'rust': {'.ok()': r'\.ok\(\)', 'unwrap_or_default': r'unwrap_or_default\(\)', 'let _ =': r'\blet _ =', 'unwrap_or(': r'\.unwrap_or\('},
    'ts': {'empty catch': r'catch\s*(\([^)]*\))?\s*\{\s*(//[^\n]*)?\s*\}', '.catch(()=>': r'\.catch\(\s*\(\)\s*=>', 'as any': r'\bas any\b'},
    'py': {'except Exception': r'except\s+(Exception|BaseException)?\s*(as \w+)?:', 'check=False': r'check\s*=\s*False', '.get(k,default)': r'\.get\([^()]*,\s*(0|None|\[\]|\{\}|\'\'|"")\)'},
    'yaml': {'|| true': r'\|\|\s*true', '2>/dev/null': r'2>\s*/dev/null', '// empty': r'//\s*empty', '|| echo': r'\|\|\s*echo'},
    'sh': {'|| true': r'\|\|\s*true', '2>/dev/null': r'2>\s*/dev/null'},
}
BARE = {
    'rust': r'assert!\([^;]*?\.(is_ok|is_err|is_some|is_none)\(\)\s*\)',
    'ts': r'\.(toBeTruthy|toBeFalsy|toBeDefined|toBeUndefined)\(',
    'py': r'\.(assertTrue|assertFalse)\(',
}
ALLOW = {
    'rust': r'#!?\[(allow|ignore|cfg_attr\(.*allow)',
    'ts': r'(eslint-disable|oxlint-disable|@ts-ignore|@ts-expect-error|@ts-nocheck|biome-ignore)',
    'py': r'(#\s*noqa|#\s*type:\s*ignore|#\s*pragma)',
    'yaml': r'(zizmor:\s*ignore|actionlint)',
}
STRLIT = re.compile(r'"([A-Za-z_][A-Za-z0-9_./:@-]{7,60})"|\'([A-Za-z_][A-Za-z0-9_./:@-]{7,60})\'')
rows, strfiles = [], collections.defaultdict(set)
for p in files:
    if not p or SKIP.search(p):
        continue
    ext = p.rsplit('.', 1)[-1]
    lang = CODE_EXT.get(ext)
    if p == 'justfile':
        lang = 'sh'
    if not lang:
        continue
    try:
        text = open(os.path.join(root, p), encoding='utf-8', errors='replace').read()
    except OSError:
        continue
    lines = text.split('\n')
    cs = comment_style(lang)
    code = com = run = longest = hist = 0
    in_block = False
    for ln in lines:
        s = ln.strip()
        if not s:
            run = 0
            continue
        is_c = False
        if lang in ('rust', 'ts'):
            if in_block:
                is_c = True
                if '*/' in s:
                    in_block = False
            elif s.startswith('/*'):
                is_c = True
                in_block = '*/' not in s
            elif s.startswith('//'):
                is_c = True
        else:
            is_c = s.startswith('#') and not s.startswith('#!')
        if is_c:
            com += 1
            run += 1
            longest = max(longest, run)
            if HIST.search(s):
                hist += 1
        else:
            code += 1
            run = 0
    soft = {}
    for name, pat in SOFT.get(lang, {}).items():
        n = len(re.findall(pat, text, re.S if name == 'empty catch' else 0))
        if n:
            soft[name] = n
    bare = len(re.findall(BARE[lang], text, re.S)) if lang in BARE else 0
    allow = len(re.findall(ALLOW[lang], text)) if lang in ALLOW else 0
    if not is_fixture(p):
        for ln in lines:
            if ln.lstrip().startswith(('use ', 'import ', 'from ', 'mod ', 'pub mod', 'pub use', '//', '#', '*')):
                continue
            for m in STRLIT.finditer(ln):
                strfiles[m.group(1) or m.group(2)].add(p)
    is_test = bool(re.search(r'(^|/)(tests?|__tests__)/|\.test\.|(^|/)test_[^/]*\.py$|/tests\.rs$|_tests?\.rs$', p))
    rows.append(dict(path=p, lang=lang, fixture=is_fixture(p), test=is_test, code=code, comment=com,
                     ratio=round(com / max(1, code + com), 2), longest_run=longest, history=hist, soft=soft,
                     soft_total=sum(soft.values()), bare=bare, allow=allow))

# hotspot score: history, long comment runs, comment ratio, soft failures, bare asserts, allows, size
def score(r):
    return (r['history'] * 3 + max(0, r['longest_run'] - 2) * 2 + r['ratio'] * 40 + r['soft_total'] * 2 + r['bare'] * 2 +
            r['allow'] * 2 + r['code'] / 400)
for r in rows:
    r['score'] = round(score(r), 1)
rows.sort(key=lambda r: -r['score'])
repeated = sorted(((s, sorted(f)) for s, f in strfiles.items() if len(f) >= 4), key=lambda x: -len(x[1]))

def sh(cmd):
    return subprocess.run(cmd, shell=True, cwd=root, capture_output=True, text=True).stdout.strip().split('\n')

ci_cmds = sh(r"grep -n -E '(cargo (nextest|test|clippy|doc|llvm-cov|semver|deny|machete)|vitest|pnpm( -r| --filter)? ?(run )?(test|lint|build)|just [a-z-]+|unittest|pytest|oxlint|oxfmt|typos|zizmor|actionlint|trycmd)' .github/workflows/*.yml | cut -c1-170")
just_recipes = sh(r"grep -n -E '^[a-z][a-z0-9_-]*( [^:]*)?:|nextest|vitest|unittest|pytest|pnpm .*test|cargo (test|llvm-cov)' justfile | cut -c1-170")
vitest_cfgs = sh(r"git ls-files | grep -E '(vitest|vite)\.config\.|package\.json$' | grep -v node_modules")
pkg_tests = sh(r"for f in $(git ls-files | grep -E '(^|/)package\.json$' | grep -v node_modules); do t=$(python3 -c \"import json,sys;d=json.load(open('$f'));s=d.get('scripts',{});print({k:v for k,v in s.items() if 'test' in k})\"); echo \"$f $t\"; done")
test_files = [r['path'] for r in rows if r['test']]
consumers = sh(r"grep -n -E '\bjq\b|--jq|fromJSON|JSON\.parse\(|json\.loads?\(|serde_json::from_(str|slice|value)|\.pending\[|toJSON' $(git ls-files | grep -E '\.(yml|py|mjs|ts|js|sh)$|^justfile$' | grep -v -E 'node_modules|fixtures|\.test\.|/tests?/|^crates/.*\.rs') 2>/dev/null | cut -c1-190")
consumers_rs = sh(r"grep -n -E 'serde_json::from_(str|slice|value)|from_reader' $(git ls-files 'crates/**/*.rs' | grep -v -E '/tests?/|tests\.rs') 2>/dev/null | cut -c1-170")
bench = sh(r"grep -n -E \"(extract|session|lazy_bench|--no-cache|--load-dependencies|--html-attributes|--collapse|hyperfine|/usr/bin/time|\\['caliper|binary,|bin,)\" scripts/bench.py scripts/weekly.py scripts/corpora.py scripts/precision-sample.py scripts/headline.py scripts/agent_eval.py packages/storybook/scripts/storybook-parity.mjs crates/core/examples/*.rs justfile 2>/dev/null | cut -c1-190")
json.dump(dict(rows=rows, repeated=repeated[:60], ci_cmds=ci_cmds, just_recipes=just_recipes, vitest_cfgs=vitest_cfgs,
               pkg_tests=pkg_tests, test_files=test_files, consumers=consumers, consumers_rs=consumers_rs, bench=bench),
          open(out, 'w'))
print('files scanned', len(rows), 'lines of code', sum(r['code'] for r in rows))

